import json, collections

# Load ontology
with open('data/wikievents/ontology_constraints_wikievents.json') as f:
    ont = json.load(f)

entity_types = set(ont['entity_types'])
event_type_mapping = ont['event_type_mapping']
event_constraints = ont['event_constraints']

# Collect all event types, entity types, and roles from data
data_event_types = collections.Counter()
data_entity_types = collections.Counter()
data_roles = collections.Counter()  # (event_type, role) -> count
role_entity_pairs = collections.Counter()  # (event_type, role, entity_type) -> count
n_docs = 0

for split in ['train', 'dev', 'test']:
    with open(f'data/wikievents/{split}.jsonl') as f:
        for line in f:
            doc = json.loads(line)
            n_docs += 1
            eid_to_type = {e['id']: e['entity_type'] for e in doc.get('entity_mentions', [])}

            for ent in doc.get('entity_mentions', []):
                data_entity_types[ent['entity_type']] += 1

            for em in doc.get('event_mentions', []):
                raw_et = em['event_type']
                data_event_types[raw_et] += 1

                for arg in em.get('arguments', []):
                    ent_type = eid_to_type.get(arg.get('entity_id', ''), 'UNK')
                    data_roles[(raw_et, arg['role'])] += 1
                    role_entity_pairs[(raw_et, arg['role'], ent_type)] += 1

print(f"Total docs: {n_docs}")
print(f"Unique event types in data: {len(data_event_types)}")
print(f"Unique entity types in data: {len(data_entity_types)}")

# Check 1: All event types in data are in ontology mapping
missing_et = []
for et in data_event_types:
    if et not in event_type_mapping:
        missing_et.append(et)
if missing_et:
    print(f"\nMISSING event types in mapping: {missing_et}")
else:
    print("\n[PASS] All data event types have mapping entries")

# Check 2: All mapped short names are in event_constraints
missing_ec = []
for full_name, short_name in event_type_mapping.items():
    if short_name not in event_constraints:
        missing_ec.append((full_name, short_name))
if missing_ec:
    print(f"MISSING event_constraints: {missing_ec}")
else:
    print("[PASS] All mapped event types have constraint entries")

# Check 3: All entity types in data are in ontology
missing_ent = []
for ent in data_entity_types:
    if ent not in entity_types:
        missing_ent.append(ent)
if missing_ent:
    print(f"MISSING entity types: {missing_ent}")
else:
    print("[PASS] All data entity types are in ontology")

# Check 4: All roles in data are in constraints for their event type
missing_roles = []
for (raw_et, role), cnt in data_roles.items():
    short_name = event_type_mapping.get(raw_et, raw_et)
    if short_name in event_constraints:
        if role not in event_constraints[short_name]['valid_roles']:
            missing_roles.append((raw_et, short_name, role, cnt))
if missing_roles:
    print(f"\nMISSING roles in constraints:")
    for raw_et, short, role, cnt in missing_roles:
        print(f"  {raw_et} ({short}): {role} (count={cnt})")
else:
    print("[PASS] All data roles are in ontology constraints")

# Check 5: All role-entity pairs are valid
invalid_pairs = []
for (raw_et, role, ent_type), cnt in role_entity_pairs.items():
    short_name = event_type_mapping.get(raw_et, raw_et)
    if short_name in event_constraints:
        rec = event_constraints[short_name]['role_entity_constraints']
        if role in rec:
            if ent_type not in rec[role]:
                invalid_pairs.append((raw_et, role, ent_type, cnt))
if invalid_pairs:
    print(f"\nRole-entity type violations ({len(invalid_pairs)}):")
    for raw_et, role, ent_type, cnt in sorted(invalid_pairs):
        print(f"  {raw_et} / {role}: {ent_type} (count={cnt})")
else:
    print("[PASS] All role-entity type pairs are valid")

print(f"\nFinal ontology: {len(ont['entity_types'])} entity types, {len(ont['event_types'])} event types")
